use regex::Regex;
use tiny_http::{Server, Response};
fn number_to_words(n:&str)->Result<String,Box<dyn std::error::Error>>{let body=format!(r#"<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><NumberToWords xmlns="http://www.dataaccess.com/webservicesserver/"><ubiNum>{}</ubiNum></NumberToWords></soap:Body></soap:Envelope>"#,n);let client=reqwest::blocking::Client::new();let xml=client.post("https://www.dataaccess.com/webservicesserver/NumberConversion.wso").header("Content-Type","text/xml; charset=utf-8").header("SOAPAction","http://www.dataaccess.com/webservicesserver/NumberToWords").body(body).send()?.text()?;let re=Regex::new(r"<m:NumberToWordsResult>(.*?)</m:NumberToWordsResult>|<NumberToWordsResult>(.*?)</NumberToWordsResult>")?;if let Some(c)=re.captures(&xml){Ok(c.get(1).or(c.get(2)).unwrap().as_str().trim().to_string())}else{Ok(xml)}}
fn main(){let server=Server::http("0.0.0.0:3000").unwrap();println!("Servidor en http://localhost:3000/?n=10");for rq in server.incoming_requests(){let url=rq.url().to_string();let n=url.split("n=").nth(1).unwrap_or("10");let out=number_to_words(n).unwrap_or_else(|e|format!("Error SOAP: {}",e));let _=rq.respond(Response::from_string(out));}}
